// Structured UI model and modeling instructions shared by the Explorer role.
const text = { type: "string" };
const strings = { type: "array", items: text };
const record = (properties) => ({
  type: "object",
  properties,
  required: Object.keys(properties),
  additionalProperties: false,
});
const records = (properties) => ({ type: "array", items: record(properties) });

export const uiModelFormat = {
  type: "json_schema",
  name: "observed_page_models",
  strict: true,
  schema: record({
    pages: records({
      name: text,
      purpose: text,
      screenshotIds: strings,
      viewVariants: records({
        name: text,
        explicitTypeLabels: records({
          label: text,
          value: text,
          screenshotIds: strings,
        }),
        distinguishingElements: records({
          name: text,
          kind: text,
          observedText: strings,
          appearance: text,
          screenshotIds: strings,
        }),
        formNames: strings,
        controlNames: strings,
        screenshotIds: strings,
        observationLimits: strings,
      }),
      forms: records({
        name: text,
        fields: records({
          name: text,
          kind: text,
          required: { type: ["boolean", "null"] },
          editable: { type: ["boolean", "null"] },
          options: strings,
          observedValues: strings,
          validationMessages: strings,
          screenshotIds: strings,
        }),
        screenshotIds: strings,
      }),
      entities: records({
        name: text,
        fields: records({
          name: text,
          observedValues: strings,
          screenshotIds: strings,
        }),
      }),
      controls: records({
        name: text,
        kind: text,
        observedStates: strings,
        screenshotIds: strings,
      }),
      states: records({
        description: text,
        screenshotIds: strings,
      }),
      connections: records({
        control: text,
        destination: text,
        basis: text,
        screenshotIds: strings,
      }),
      observationLimits: strings,
    }),
    unknowns: strings,
  }),
};

export const uiModelInstruction =
  "Describe observed pages, forms, fields, controls, states and navigation. Record visible labels, options, layouts and validation messages. Cite the screenshot IDs that show them. Distinguish observations from inferred behavior. Use null when a field’s required or editable state is unknown. Group repeated views while preserving meaningful differences. Report task-related gaps in the app model.";
